#include <cstdint>
#include "address.h"
#include "modules.h"
#include <vector>
#include <algorithm> // For std::min, std::max

// Define constants for the prefetcher's behavior
constexpr int NUM_STREAMS = 16;          // Number of active streams/regions to track
constexpr int PREFETCH_DISTANCE = 8;     // How many cache lines ahead to prefetch
constexpr int INITIAL_CONFIDENCE = 5;    // Starting confidence for a new stream
constexpr int CONFIDENCE_THRESHOLD = 3;  // Minimum confidence to issue a prefetch
constexpr int CONFIDENCE_INCREMENT = 2;  // Amount to increase confidence on useful prefetch
constexpr int CONFIDENCE_DECREMENT = 1;  // Amount to decrease confidence on miss
constexpr int MAX_CONFIDENCE = 10;       // Upper bound for confidence
constexpr int MIN_CONFIDENCE = 0;        // Lower bound for confidence

// Structure to hold state for each detected stream/region
struct StreamState {
    champsim::block_number last_block;      // The last block address accessed in this stream
    int confidence;                         // Confidence level for this stream
    unsigned long long last_access_cycle;   // Cycle of last access, used for LRU replacement
    bool valid;                             // Indicates if this stream entry is active

    // Default constructor to initialize fields
    StreamState() : last_block{}, confidence(0), last_access_cycle(0), valid(false) {}
};

struct gen_aggressive_offset_s2 : public champsim::modules::prefetcher {
    using prefetcher::prefetcher;

    std::vector<StreamState> streams;      // Table to store active stream states
    unsigned long long current_cycle;      // Global cycle counter for LRU tracking

    // Constructor for the prefetcher module
    gen_aggressive_offset_s2() : prefetcher(), streams(NUM_STREAMS), current_cycle(0) {
        // Initialize all stream entries as invalid
        for (auto& s : streams) {
            s.valid = false;
        }
    }

    // Called on every core-cache access
    uint32_t prefetcher_cache_operate(champsim::address addr, champsim::address ip,
                                       uint8_t cache_hit, bool useful_prefetch,
                                       access_type type, uint32_t metadata_in) {
        current_cycle++; // Increment global cycle counter

        // Convert the accessed address to a block number for arithmetic
        champsim::block_number current_blk{addr};

        StreamState* current_stream = nullptr;
        // Search for a matching sequential stream
        for (auto& s : streams) {
            if (s.valid) {
                // Check if current_blk is a sequential continuation of this stream
                champsim::block_number::difference_type diff = champsim::offset(s.last_block, current_blk);
                if (diff == 1) { // Found a sequential access pattern
                    current_stream = &s;
                    break;
                }
            }
        }

        if (current_stream) {
            // Update the state of the found stream
            current_stream->last_block = current_blk;
            current_stream->last_access_cycle = current_cycle;

            // Update confidence based on feedback
            if (useful_prefetch) {
                // Prefetch was useful, increase confidence
                current_stream->confidence = std::min(current_stream->confidence + CONFIDENCE_INCREMENT, MAX_CONFIDENCE);
            } else if (!cache_hit) {
                // Cache miss (and not a useful prefetch), indicates prefetcher might have failed or not acted
                current_stream->confidence = std::max(current_stream->confidence - CONFIDENCE_DECREMENT, MIN_CONFIDENCE);
            }

            // Issue a prefetch if confidence is high enough
            if (current_stream->confidence >= CONFIDENCE_THRESHOLD) {
                champsim::block_number pf_blk = current_blk + PREFETCH_DISTANCE;
                // Prefetch the block into the current cache level (true)
                prefetch_line(champsim::address{pf_blk}, true, metadata_in);
            }
        } else {
            // No matching sequential stream found.
            // Attempt to create a new stream entry or replace an old one (LRU).

            StreamState* new_stream_entry = nullptr;
            StreamState* lru_entry = nullptr;
            unsigned long long min_cycle = -1ULL; // Initialize with max value for LRU tracking

            // Find an invalid entry or the Least Recently Used (LRU) entry
            for (auto& s : streams) {
                if (!s.valid) {
                    new_stream_entry = &s; // Found an empty slot, prioritize this
                    break;
                }
                if (s.last_access_cycle < min_cycle) {
                    min_cycle = s.last_access_cycle;
                    lru_entry = &s;
                }
            }

            // If no invalid entry was found, use the LRU entry for replacement
            if (new_stream_entry == nullptr) {
                new_stream_entry = lru_entry;
            }

            if (new_stream_entry) { // A slot should always be available if NUM_STREAMS > 0
                new_stream_entry->valid = true;
                new_stream_entry->last_block = current_blk;
                new_stream_entry->confidence = INITIAL_CONFIDENCE; // Start with initial confidence
                new_stream_entry->last_access_cycle = current_cycle;
                // No prefetch is issued for a newly created stream;
                // it needs to observe sequential access first.
            }
        }

        return metadata_in;
    }

    // Called on a fill into the cache being modelled
    uint32_t prefetcher_cache_fill(champsim::address addr, long set, long way,
                                    uint8_t prefetch, champsim::address evicted_addr,
                                    uint32_t metadata_in) {
        // This prefetcher primarily uses the `useful_prefetch` signal in
        // `prefetcher_cache_operate` for confidence updates.
        // No specific action is needed here for this design.
        return metadata_in;
    }
};

